import { useQuery } from '@tanstack/react-query'
import { toast } from 'sonner'
import { TemplateCard } from '@/shared/ui/TemplateCard'
import { templatesService } from '@/integrations/supabase/templates'
import { useTenant } from '@/app/providers/TenantProvider'

export function TemplatesMarketplacePage() {
  const { manifest } = useTenant()
  const { data: templates = [], isLoading } = useQuery({
    queryKey: ['templates', manifest?.tenantId],
    queryFn: () => templatesService.listTemplates(manifest?.tenantId),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-5xl mx-auto">
        <h2 className="font-semibold mb-6">Project templates</h2>
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : templates.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground">No templates available yet</p>
          </div>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {templates.map((t) => (
              <TemplateCard key={t.id} template={t}
                onPreview={() => toast.info(`Preview: ${t.title}`)}
                onUse={() => toast.success(`Template "${t.title}" applied`)} />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
